import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Workspace バックエンド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/self-hosted/workspace-backends.md","filePath":"ja/self-hosted/workspace-backends.md","lastUpdated":1792323081000}'),n={name:"ja/self-hosted/workspace-backends.md"};function l(o,s,p,d,r,h){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="workspace-バックエンド" tabindex="-1">Workspace バックエンド <a class="header-anchor" href="#workspace-バックエンド" aria-label="Permalink to &quot;Workspace バックエンド&quot;">​</a></h1><p>どの Memoh Bot もワークスペースの中で働きます。ワークスペースは隔離されたコンテナにも、Desktop／ローカル構成で明示的に信頼したホスト上のディレクトリにもなります。バックエンドは、ワークスペースがどこで動くか、そして隔離・ネットワーク・スナップショット・display 機能が使えるかどうかを決めます。</p><h2 id="コンテナバックエンド" tabindex="-1">コンテナバックエンド <a class="header-anchor" href="#コンテナバックエンド" aria-label="Permalink to &quot;コンテナバックエンド&quot;">​</a></h2><p>コンテナワークスペースは <code>config.toml</code> で設定します：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;containerd&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # containerd、docker または apple</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Backend</th><th>向いている場面</th><th>説明</th></tr></thead><tbody><tr><td><code>containerd</code></td><td>Docker Compose の Server Deploy、Linux サーバー、開発環境</td><td>公式 server イメージの既定。CNI ネットワーク、スナップショット、CDI デバイス、provider sidecar に対応し、ローカルワークスペース機能が最も充実。</td></tr><tr><td><code>docker</code></td><td>Memoh をホスト上で直接動かし、ホストに Docker Engine がある</td><td>ホストの Docker API を使用。<code>container.runtime_dir</code> のような bind mount のソースパスは Docker ホスト上に実在する必要がある。</td></tr><tr><td><code>apple</code></td><td>macOS でのローカルテスト</td><td>socktainer と Apple Containerization 経由。provider sidecar は非対応。</td></tr></tbody></table><p>ワンライナーの Docker Compose Server Deploy は <code>containerd</code> に固定されています。これは意図的な仕様です：server イメージは内蔵 containerd を起動し、Bot ワークスペースに必要な runtime ファイルをマウントします。<code>docker</code> と <code>apple</code> は、ホストの runtime パスを自分で管理できる手動デプロイに向いています。</p><h2 id="信頼済みローカルワークスペース" tabindex="-1">信頼済みローカルワークスペース <a class="header-anchor" href="#信頼済みローカルワークスペース" aria-label="Permalink to &quot;信頼済みローカルワークスペース&quot;">​</a></h2><p>Desktop とローカル開発では、コンテナバックエンドに加えて信頼済みローカルワークスペースを有効化できます：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>信頼済みローカルワークスペースは、server プロセスの権限でホスト上で直接動きます。個人のデスクトップワークフローやローカル開発には向きますが、<strong>コンテナ隔離はありません</strong>。信頼できない server デプロイでは local ワークスペースを有効にしないでください。</p><p>Bot が local ワークスペースを使っている場合、コンテナデスクトップやコンテナ display セッションに依存する UI 機能は非表示または利用不可になることがあります。</p><h2 id="containerd" tabindex="-1">containerd <a class="header-anchor" href="#containerd" aria-label="Permalink to &quot;containerd&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;containerd&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_image = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;debian:bookworm-slim&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">image_pull_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;if_not_present&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">snapshotter = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;overlayfs&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data_root = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/data&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/runtime&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cni_bin_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/cni/bin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cni_conf_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/cni/net.d&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">containerd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socket_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/run/containerd/containerd.sock&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">namespace = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span></code></pre></div><p>公式の Docker Compose スタックと、containerd に直接つなぐ Linux ホストの両方がこれを使います。</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docker&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_image = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;debian:bookworm-slim&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/runtime&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data_root = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/data&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 空のままにすると Docker の標準的な環境検出を使います：DOCKER_HOST、</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># DOCKER_TLS_VERIFY、DOCKER_CERT_PATH、またはプラットフォーム既定の socket。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Docker バックエンドは標準の Docker 環境経由で Docker Engine に接続します。Memoh サービスがホスト上で直接動くデプロイや、Docker bind mount のソースパスが実際のホストパスであることを保証できる環境に向いています。</p><p>公式 Docker Compose インストールの <code>containerd</code> を、Docker socket と <code>runtime_dir</code> のホストパスを両方きちんと処理しないまま <code>docker</code> に変えないでください。ワークスペースコンテナは作れても、bridge runtime ファイルを受け取れなくなることがあります。</p><h2 id="apple" tabindex="-1">Apple <a class="header-anchor" href="#apple" aria-label="Permalink to &quot;Apple&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apple&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apple</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socket_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">binary_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Apple バックエンドは socktainer と Apple Containerization による macOS ローカルテスト用です。まだ実験的な機能で、provider sidecar には対応していません。</p><h2 id="display・browser-use・computer-use" tabindex="-1">Display・Browser Use・Computer Use <a class="header-anchor" href="#display・browser-use・computer-use" aria-label="Permalink to &quot;Display・Browser Use・Computer Use&quot;">​</a></h2><p>コンテナワークスペースは display runtime を提供できます：Xvnc/RFB がワークスペースのデスクトップ表示と入力の基盤になり、ヘッド付き Chrome/Chromium が CDP を提供し、クライアントの <strong>Desktop</strong> ペインが WebRTC でセッションを開きます。</p><p>ウェブサイトが本物のグラフィカルブラウザを要求するときは、この経路を使います。Headless Playwright も通常のワークスペースコマンドとして実行できますが、Browser Use と Computer Use はヘッド付きワークスペースデスクトップを前提にしています。</p><p>local ワークスペースには同等のコンテナデスクトップ隔離はありません。ツールレベルの違いは <a href="./../guides/browser-computer-use.html">Browser / Computer Use</a> を参照してください。</p><h2 id="ネットワークと-overlay" tabindex="-1">ネットワークと overlay <a class="header-anchor" href="#ネットワークと-overlay" aria-label="Permalink to &quot;ネットワークと overlay&quot;">​</a></h2><p>Bot のネットワークは二層あります：</p><ul><li>runtime network：ワークスペースを基盤のコンテナ／Pod ネットワークにつなぐ。</li><li>overlay provider：Tailscale や NetBird などで、個別の Bot にプライベートネットワークを追加できる。</li></ul><p>バックエンドごとに対応が異なります：</p><table tabindex="0"><thead><tr><th>Backend</th><th>Runtime network</th><th>Overlay sidecar</th><th>CDI デバイス</th><th>コンテナ display</th></tr></thead><tbody><tr><td><code>containerd</code></td><td>CNI</td><td>対応</td><td>対応</td><td>対応</td></tr><tr><td><code>docker</code></td><td>Docker コンテナネットワークに参加</td><td>Docker runtime の能力に依存</td><td>非対応</td><td>runtime ファイルとイメージ側のコンポーネントが揃えば対応</td></tr><tr><td><code>apple</code></td><td>基盤のローカル runtime</td><td>非対応</td><td>非対応</td><td>限定的</td></tr><tr><td><code>local</code></td><td>ホストネットワーク</td><td>非対応</td><td>ホストレベル</td><td>コンテナデスクトップなし</td></tr></tbody></table><p>overlay provider は Bot の画面で設定し、グローバルの TOML では設定しません。それでもグローバルのバックエンドは重要です——どの種類の overlay driver を動かせるかを決めるからです。</p><h2 id="cdi-デバイス-gpu-パススルー" tabindex="-1">CDI デバイス（GPU パススルー） <a class="header-anchor" href="#cdi-デバイス-gpu-パススルー" aria-label="Permalink to &quot;CDI デバイス（GPU パススルー）&quot;">​</a></h2><p>ホストのデバイスを <strong>CDI</strong>（最も一般的なのは GPU）でコンテナ型ワークスペースに渡すには、その Bot の <strong>Workspace</strong> → <strong>Advanced</strong> で設定します。ワークスペース内で実際に CUDA/ROCm などを動かす必要があるときだけ触れば十分です。</p><h3 id="設定手順" tabindex="-1">設定手順 <a class="header-anchor" href="#設定手順" aria-label="Permalink to &quot;設定手順&quot;">​</a></h3><ol><li><strong>Workspace</strong> タブを開きます。コンテナがなければ先に <strong>作成</strong> します。</li><li><strong>Advanced</strong> を展開して <strong>GPU</strong> を有効にし、<strong>CDI devices</strong> にデバイス名を 1 行 1 つ、またはカンマ区切りで入力します： <ul><li><code>nvidia.com/gpu=0</code>、<code>nvidia.com/gpu=all</code></li><li><code>amd.com/gpu=0</code>、<code>amd.com/gpu=all</code></li></ul></li></ol><h3 id="ホスト側の要件" tabindex="-1">ホスト側の要件 <a class="header-anchor" href="#ホスト側の要件" aria-label="Permalink to &quot;ホスト側の要件&quot;">​</a></h3><p>ドライバー、ベンダーツール、CDI spec がホスト上に揃っている必要があります。通常は次を意味します：</p><ul><li>GPU がホスト上でそもそも動いている</li><li><code>/etc/cdi</code> か <code>/var/run/cdi</code> に spec がある</li><li>入力した名前がランタイムから見える名前と一致している（NVIDIA は <code>nvidia-ctk cdi list</code>、AMD は <code>amd-ctk cdi list</code> で確認）</li></ul><p><code>unresolvable CDI devices</code> エラーは、ほぼ名前の不一致です。</p><h3 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h3><ul><li>CDI は<strong>作成</strong>時に効きます：設定を変えたら通常はコンテナの<strong>再作成</strong>が必要で、停止→起動だけでは接続済みデバイスは<strong>入れ替わりません</strong>。</li><li>CUDA/ROCm ソフトウェアを実際に動かすには、イメージ側にも正しいユーザーランドのライブラリとツールが必要です。</li><li>作成後は <strong>Workspace</strong> タブに現在接続されているデバイスが表示されるので、確認に使えます。</li><li>バックエンドごとの対応は上の表のとおり——CDI に対応するのは <code>containerd</code> だけです。</li></ul>`,42)])])}const E=a(n,[["render",l]]);export{c as __pageData,E as default};
